/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

interface ScoreBugProps {
  /** The opponent's name, set in caps on the right block. The left block is always the remocn logo. */
  away?: string;
  /** Goals remocn scores, one digit flip each. */
  score?: number;
  /** The opponent's score, shown from the start. */
  awayScore?: number;
  /** One scorer line per goal, under the remocn block. Use the prime for minutes: "Ship 47′". */
  scorers?: string[];
  /** Word on the flash band that sweeps across after the last goal. */
  flash?: string;
  /** Tab label while the match runs. */
  liveLabel?: string;
  /** Tab label once the band has passed. */
  finalLabel?: string;
  /** The live marker in the tab and the scorer ticks. */
  accent?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the scores and labels. Load it yourself; Barlow Condensed by default. */
  fontFamily?: string;
  /** Frame of the first goal. */
  firstGoal?: number;
  /** Frames between goals. */
  goalGap?: number;
  /** Replaces the remocn mark on the home block. */
  logo?: React.ReactNode;
  /** Size of the panel and band, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (internal clock = frame + 2, 30fps, speed 1, score 2):
//  -2–4    the white score core slams open from its centre line
//   3–13   both team blocks shoot out from behind the core; names follow
//  12–19   the "Live" tab rises from behind the panel
//  30      goal: the home digit flips 0→1 (6f), the panel kicks, the remocn
//          block flashes and the scorer line drops in under it
//  48      goal: 1→2, same mechanic
//  60–82   the gradient "Shipped" band sweeps across; while it covers the
//          panel the tab turns to "Full time" and the opponent dims
//  82–     poster scoreline holds
const GOAL_AT = 30;
const GOAL_GAP = 18;
const FLIP = 6;
const BAND_DELAY = 12;
const BAND_IN = 7;
const BAND_HOLD = 9;
const BAND_OUT = 7;

const SLAM = Easing.bezier(0.22, 1, 0.36, 1);
const FLIPEASE = Easing.bezier(0.7, 0, 0.25, 1);
const EXIT = Easing.bezier(0.6, 0, 0.9, 0.4);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "beam": #f4f7ff, #8fb4ff, #3d5bff, #1a1660.
const BEAM = ["#F4F7FF", "#8FB4FF", "#3D5BFF", "#1A1660"] as const;

const THEMES = {
  dark: {
    stage: "#0A0A0B",
    core: "#F3F2EF",
    coreInk: "#0A0A0B",
    coreRule: "#D9D7D1",
    away: "#1C1C20",
    awayOff: "#131316",
    awayInk: "#F3F2EF",
    awayDim: "#4D4C53",
    tab: "#1C1C20",
    tabInk: "#F3F2EF",
    dim: "#86858C",
  },
  light: {
    stage: "#F5F4F0",
    core: "#121214",
    coreInk: "#F5F4F0",
    coreRule: "#2A2A2E",
    away: "#E2E0D9",
    awayOff: "#EAE8E2",
    awayInk: "#121214",
    awayDim: "#B3B1AA",
    tab: "#121214",
    tabInk: "#F5F4F0",
    dim: "#7E7D77",
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** A short hit: up in 2 frames, eases back over 9. */
function kick(d: number) {
  if (d < 0) return 0;
  if (d < 2) return d / 2;
  const k = Math.max(0, 1 - (d - 2) / 9);
  return k * k;
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function ScoreBugBase({
  away = "Old way",
  score = 2,
  awayScore = 0,
  scorers = ["Install 12′", "Ship 47′"],
  flash = "Shipped",
  liveLabel = "Live · 2nd half",
  finalLabel = "Full time",
  accent = "#3B5BFD",
  background,
  fontFamily = condensed,
  firstGoal = GOAL_AT,
  goalGap = GOAL_GAP,
  logo,
  scale = 1,
  delay = 0,
  theme = "dark",
  speed = 1,
}: ScoreBugProps) {
  const glide = useGlide();
  // Starts two frames in, so frame 0 already shows the core opening.
  const t = Math.max(0, useCurrentFrame() - delay) * speed + 2;
  const { width: W, height: H } = useVideoConfig();
  const c = THEMES[theme];
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.stage);
  const u = Math.min(W / 1280, H / 720);

  const goals = Math.max(0, Math.floor(score));
  const goalAt = Array.from(
    { length: goals },
    (_, i) => firstGoal + i * goalGap,
  );
  const bandAt = (goalAt[goals - 1] ?? firstGoal - goalGap) + BAND_DELAY;
  const fullTimeAt = bandAt + BAND_IN + 4;
  const fullTime = t >= fullTimeAt;

  // ── Layout ────────────────────────────────────────────────────────────────
  const panelW = 1160 * u;
  const panelH = 250 * u;
  const coreW = 360 * u;
  const gap = 8 * u;
  const blockW = (panelW - coreW - 2 * gap) / 2;
  const panelX = (W - panelW) / 2;
  const panelY = (H - panelH) / 2 - 14 * u;
  const tabH = 52 * u;
  const digitFs = 270 * u;
  const cellW = 140 * u;

  // ── Entrance ──────────────────────────────────────────────────────────────
  const coreOpen = SLAM(ramp(t, 0, 6));
  const blockOut = SLAM(ramp(t, 3, 10));
  const nameIn = SLAM(ramp(t, 8, 9));
  const digitIn = SLAM(ramp(t, 6, 8));
  const tabUp = SLAM(ramp(t, 12, 8));

  // Every hit nudges the panel up in scale for a beat.
  const hits = [5, ...goalAt.map((g) => g + 2)];
  const bumpAt = (at: number) =>
    hits.reduce((a, h) => Math.max(a, kick(at - h)), 0);
  const panelScale = 1 + 0.022 * bumpAt(t);
  // The kick has no clean progress, so the panel counts as moving whenever
  // its edge steps against either neighbouring frame.
  const bumping =
    Math.abs(bumpAt(t + speed) - bumpAt(t)) * 0.022 * W > 1e-3 ||
    Math.abs(bumpAt(t) - bumpAt(t - speed)) * 0.022 * W > 1e-3;

  // Home digit: which goal is flipping, and how far.
  let home = 0;
  let flipP = 1;
  for (let i = 0; i < goals; i++) {
    if (t >= goalAt[i]) {
      home = i + 1;
      flipP = FLIPEASE(ramp(t, goalAt[i], FLIP));
    }
  }
  const prev = home - 1;

  const blockFlash = goalAt.reduce((a, g) => {
    const d = t - g - 1;
    if (d < 0 || d > 10) return a;
    return Math.max(a, (1 - d / 10) ** 2);
  }, 0);

  const awayDimP = ramp(t, fullTimeAt, 6);
  const awayBg = fullTime ? c.awayOff : c.away;
  const awayInk = awayDimP > 0 ? c.awayDim : c.awayInk;

  // Gentle drift on the home block's gradient.
  const drift = interpolate(t, [0, 120], [0, 10], CLAMP);
  const homeGround = [
    `radial-gradient(70% 140% at ${10 + drift}% 0%, ${BEAM[1]}e6 0%, transparent 62%)`,
    `radial-gradient(60% 120% at ${96 - drift * 0.6}% 110%, ${BEAM[2]} 0%, transparent 72%)`,
    `linear-gradient(115deg, ${BEAM[3]} 0%, #2B3BCF 100%)`,
  ].join(", ");

  // ── Band ──────────────────────────────────────────────────────────────────
  const rowH = 40 * u;
  const bandTop = panelY - tabH - gap - 14 * u;
  const bandBottom =
    panelY +
    panelH +
    14 * u +
    Math.max(1, Math.min(goals, scorers.length)) * rowH +
    14 * u;
  const bandH = bandBottom - bandTop;
  const slant = 0.2 * bandH;
  const bandIn = SLAM(ramp(t, bandAt, BAND_IN));
  const bandOut = EXIT(ramp(t, bandAt + BAND_IN + BAND_HOLD, BAND_OUT));
  const span = W + 2 * slant;
  const bandX = -span * (1 - bandIn) + span * bandOut;
  const hold = ramp(t, bandAt + BAND_IN, BAND_HOLD);
  const textLag =
    -0.16 * W * (1 - bandIn) + 0.025 * W * hold + 0.22 * W * bandOut;
  const bandVisible = t >= bandAt && bandOut < 1;
  const bandY = bandTop;

  const digit = (n: number, y: number, moving: boolean, key: string) => (
    <div
      key={key}
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        top: 0,
        height: panelH,
        transform: `translateY(${y}px)${glide(moving && !bumping)}`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily,
        fontWeight: 500,
        fontSize: digitFs,
        lineHeight: 1,
        color: c.coreInk,
        fontVariantNumeric: "tabular-nums",
        letterSpacing: "-0.02em",
        paddingTop: 4 * u,
      }}
    >
      {n}
    </div>
  );

  const dropIn = -(1 - digitIn) * panelH * 1.05;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `scale(${panelScale})${glide(bumping)}`,
            transformOrigin: `${W / 2}px ${panelY + panelH / 2}px`,
          }}
        >
          {/* Tab, rising from behind the panel. */}
          <div
            style={{
              position: "absolute",
              left: panelX + blockW + gap,
              top: panelY - tabH - gap,
              width: coreW,
              height: tabH + gap,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                width: coreW,
                height: tabH,
                transform: `translateY(${(1 - tabUp) * (tabH + gap)}px)${glide(midway(tabUp) && !bumping)}`,
                background: c.tab,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                gap: 12 * u,
                fontFamily,
                fontWeight: 500,
                fontSize: 28 * u,
                letterSpacing: "0.1em",
                textTransform: "uppercase",
                color: c.tabInk,
              }}
            >
              {fullTime ? null : (
                <div
                  style={{
                    width: 11 * u,
                    height: 11 * u,
                    background: accent,
                    opacity: Math.floor(t / 15) % 2 === 0 ? 1 : 0.35,
                  }}
                />
              )}
              <span style={{ paddingTop: 2 * u }}>
                {fullTime ? finalLabel : liveLabel}
              </span>
            </div>
          </div>

          {/* Home block: emerges from behind the core to the left. */}
          <div
            style={{
              position: "absolute",
              left: panelX,
              top: panelY,
              width: blockW,
              height: panelH,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                transform: `translateX(${(1 - blockOut) * (blockW + gap)}px)`,
                background: homeGround,
              }}
            >
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: "#FFFFFF",
                  opacity: 0.4 * blockFlash,
                }}
              />
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  transform: `translateX(${(1 - nameIn) * 60 * u}px)`,
                  opacity: nameIn,
                }}
              >
                {logo ?? <RemocnLogo fontSize={86 * u} color="#FFFFFF" />}
              </div>
            </div>
          </div>

          {/* Away block: emerges from behind the core to the right. */}
          <div
            style={{
              position: "absolute",
              left: panelX + blockW + coreW + 2 * gap,
              top: panelY,
              width: blockW,
              height: panelH,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                transform: `translateX(${-(1 - blockOut) * (blockW + gap)}px)`,
                background: awayBg,
              }}
            >
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  transform: `translateX(${-(1 - nameIn) * 60 * u}px)`,
                  opacity: nameIn,
                  fontFamily,
                  fontWeight: 500,
                  fontSize: 116 * u,
                  lineHeight: 1,
                  letterSpacing: "0.005em",
                  textTransform: "uppercase",
                  color: awayInk,
                  paddingTop: 6 * u,
                  whiteSpace: "nowrap",
                }}
              >
                {away}
              </div>
            </div>
          </div>

          {/* Core: the score itself. */}
          <div
            style={{
              position: "absolute",
              left: panelX + blockW + gap,
              top: panelY,
              width: coreW,
              height: panelH,
              background: c.core,
              clipPath: `inset(${50 * (1 - coreOpen)}% 0 ${50 * (1 - coreOpen)}% 0)`,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: coreW / 2 - 22 * u - cellW,
                top: 0,
                width: cellW,
                height: panelH,
                overflow: "hidden",
              }}
            >
              {flipP < 1 && prev >= 0
                ? [
                    digit(prev, -flipP * panelH, midway(flipP), "out"),
                    digit(home, (1 - flipP) * panelH, midway(flipP), "in"),
                  ]
                : digit(home, dropIn, midway(digitIn), "now")}
            </div>
            <div
              style={{
                position: "absolute",
                left: coreW / 2 - 15 * u,
                top: panelH / 2 - 4 * u,
                width: 30 * u,
                height: 9 * u,
                background: c.coreRule,
                opacity: digitIn,
              }}
            />
            <div
              style={{
                position: "absolute",
                left: coreW / 2 + 22 * u,
                top: 0,
                width: cellW,
                height: panelH,
                overflow: "hidden",
              }}
            >
              {digit(awayScore, dropIn, midway(digitIn), "away")}
            </div>
          </div>

          {/* Scorer lines under the home block. */}
          {scorers.slice(0, goals).map((line, i) => {
            const p = SLAM(ramp(t, goalAt[i] + 4, 8));
            return (
              <div
                key={`${i}-${line}`}
                style={{
                  position: "absolute",
                  left: panelX,
                  top: panelY + panelH + 14 * u + i * rowH,
                  width: blockW,
                  height: rowH,
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 12 * u,
                    height: rowH,
                    transform: `translateY(${-(1 - p) * rowH}px)${glide(midway(p))}`,
                    fontFamily,
                    fontWeight: 500,
                    fontSize: 30 * u,
                    letterSpacing: "0.06em",
                    textTransform: "uppercase",
                    color: c.dim,
                  }}
                >
                  <div
                    style={{
                      width: 4 * u,
                      height: 20 * u,
                      background: accent,
                      flexShrink: 0,
                    }}
                  />
                  <span style={{ paddingTop: 2 * u }}>{line}</span>
                </div>
              </div>
            );
          })}
        </div>

        {/* The flash band. */}
        {bandVisible ? (
          <div
            style={{
              position: "absolute",
              left: bandX - slant,
              top: bandY,
              width: span,
              height: bandH,
              clipPath: `polygon(${slant}px 0, 100% 0, calc(100% - ${slant}px) 100%, 0 100%)`,
              background: `linear-gradient(90deg, ${BEAM[3]} 0%, #2A3BD8 40%, ${BEAM[2]} 72%, ${BEAM[1]} 93%, ${BEAM[0]} 100%)`,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transform: `translateX(${textLag}px)`,
                fontFamily,
                fontWeight: 500,
                fontSize: 340 * u,
                lineHeight: 1,
                letterSpacing: "0.01em",
                textTransform: "uppercase",
                color: "#FFFFFF",
                paddingTop: 10 * u,
                whiteSpace: "nowrap",
              }}
            >
              {flash}
            </div>
          </div>
        ) : null}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

