const ELEMENT_PROP_KEYS = new Set(["theme","away","flash","liveLabel","finalLabel","score","awayScore","firstGoal","goalGap","accent","fontFamily","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  away: "Old way",
  flash: "Shipped",
  liveLabel: "Live · 2nd half",
  finalLabel: "Full time",
  score: 2,
  awayScore: 0,
  firstGoal: 30,
  goalGap: 18,
  accent: "#3B5BFD",
  fontFamily: "Barlow Condensed",
  scale: 1,
  delay: 0,
  speed: 1,
};

type ScoreBugElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ScoreBugBase>;

const ScoreBugInner = forwardRef<
  HTMLDivElement,
  ScoreBugElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ScoreBug>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ScoreBugBase
          {...(componentProps as unknown as ComponentProps<typeof ScoreBugBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ScoreBug = Interactive.withSchema({
  Component: ScoreBugInner,
  componentName: "<ScoreBug>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
